scenarios.example_code:
import { registerHandle } from '@projexlight/sdk-social';
const { handle_id } = await registerHandle({
  tenant_id, platform: 'linkedin',
  username: 'acme-inc', oauth_code,
});

import { ingestInteraction } from '@projexlight/sdk-social';
await ingestInteraction({
  handle_id, platform_message_id: '...',
  kind: 'mention', from_user, body, occurred_at,
});

import { captureLead } from '@projexlight/sdk-social';
const { lead_id } = await captureLead({
  interaction_id, owner_persona_id: round_robin_sdr.id,
  rule_matched: 'director-plus-mid-market',
});

import { startSocialPoller } from '@projexlight/sdk-social';
startSocialPoller({
  handle_id, interval_min: 5,
});

subscribeEvents('social.interaction.ingested.v1', async (e) => {
  if (e.payload.kind !== 'dm') return;
  await openConversationThread({ source_kind: 'instagram-dm', interaction_id: e.payload.interaction_id });
});
